import json,urllib.request,urllib.parse
base='http://127.0.0.1:17448'
p=json.loads(urllib.request.urlopen(base+'/api/supervisor-watchdog/projects',timeout=10).read().decode('utf-8'))
projects=p.get('projects') or p.get('managedProjects') or []
out={'projects':[{'id':x.get('id'),'name':x.get('name'),'profileId':x.get('profileId'),'enabled':x.get('enabled')} for x in projects],'previews':[]}
for cid in ['chat-6abf3eb2-40ec-83eb-9f7f-c4a32ad11fc0','agent-pc-control']:
 for proj in projects:
  pid=str(proj.get('id') or '')
  if not pid: continue
  u=base+'/api/supervisor-watchdog/managed-chats/'+cid+'/legacy-rebind?projectId='+urllib.parse.quote(pid,safe='')
  try:
   d=json.loads(urllib.request.urlopen(u,timeout=6).read().decode('utf-8'))
   out['previews'].append({'chatId':cid,'projectId':pid,'projectName':proj.get('name'),'eligible':d.get('eligible'),'reason':d.get('reason'),'managedProfileId':d.get('managedProfileId'),'projectProfileId':d.get('projectProfileId'),'url':d.get('managedChatUrl')})
  except Exception as e:
   out['previews'].append({'chatId':cid,'projectId':pid,'error':type(e).__name__+': '+str(e)})
print(json.dumps(out,ensure_ascii=True,separators=(',',':')))
